const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const geometry=[['d','型鋼全深','mm'],['bf','翼板寬度','mm'],['tw','腹板厚度','mm'],['tf','翼板厚度','mm'],['k','外緣至圓角趾端','mm'],['h','腹板淨深','mm']];
const forces=[['Fy','腹板降伏應力','kgf/cm²'],['E','彈性模數','kgf/cm²'],['P','集中壓力需求','kgf'],['N','承壓長度','mm'],['a','載重點至最近端距','mm'],['Lb','最大無側撐長度','mm'],['M','載重點需求彎矩 |Mr|','kgf·cm'],['My','斷面降伏彎矩','kgf·cm']];
const fields=[...geometry,...forces], allKeys=Object.keys(SteelCalc.defaults);let current,result;
function fillFields(id,arr){$(id).innerHTML=arr.map(([key,label,unit])=>'<label for="'+key+'">'+label+' <span class="symbol">'+key+'</span><input id="'+key+'" type="number" step="any" min="0" required aria-label="'+label+' '+key+' '+unit+'"><span class="help">'+unit+'</span></label>').join('');}fillFields('geometry',geometry);fillFields('forces',forces);
function read(){let x={};for(let key of allKeys)x[key]=fields.some(f=>f[0]===key)?($(key).value.trim()===''?NaN:Number($(key).value)):$(key).value;return x;}
function apply(x){for(let key of allKeys)if($(key))$(key).value=x[key]??SteelCalc.defaults[key];render();}
const num=(n,d=0)=>Number(n).toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d});
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000);}
function render(){current=read();result=SteelCalc.calculate(current);const asd=current.code==='aisc-asd';$('loadHelp').textContent=asd?'請輸入 ASD 工作載重組合需求 P 與 Mr；本工具不自動組合載重。':'請輸入因數化載重組合需求 P 與 Mr；本工具不自動乘載重係數。';for(let key of ['d','bf','h','tw','P','a','N','Lb'])$('dim-'+key).textContent=key+' = '+num(current[key]);$('bottomLoad').style.display=current.load==='double'?'':'none';$('loadCaption').textContent=current.load==='double'?'同斷面雙側壓力，各為 P':'集中壓力沿腹板中心線傳入';let invalid=result.errors.length>0;$('error').hidden=!invalid;$('error').textContent=result.errors.join('；');$('excel').disabled=invalid;$('print').disabled=invalid;if(invalid){$('output').innerHTML='';return;}
let r=result,g=r.governing,overall=!r.pass?'有項目不通過':r.review?'部分條件需另行評估':'所列適用項目通過',tone=!r.pass?'fail':r.review?'review':'';let head='<section class="summary '+tone+'"><div><div class="small-label">CHECK SUMMARY · '+esc(current.member)+'</div><h2>'+overall+'</h2><p>控制項目：'+g.name+' · '+(asd?'容許強度':'設計強度')+' '+num(g.cap)+' kgf</p></div><div class="big-ratio"><strong>'+num(g.ratio,3)+'</strong><span>最大需求／容量比 · ≤ 1.000</span></div></section>';
let cards=r.rows.map((v,i)=>{let active=v.state==='calc',badge=v.state==='review'?'review':!active?'na':v.ratio>1?'fail':'';return '<article class="result-card"><div class="card-top"><h3>'+v.name+'</h3><span class="badge '+badge+'">'+v.status+'</span></div><div class="ref">'+v.ref+'</div><div class="capacity">'+(active?num(v.cap):'—')+' <small>'+(active?'kgf':'')+'</small></div><div class="card-bottom"><span>'+(active?(asd?'容許強度 Rn/Ω':'設計強度 φRn'):'請見適用條件')+'</span><span>'+(active?'D/C '+num(v.ratio,3):'')+'</span></div><div class="bar"><i class="'+badge+'" style="width:'+(active?Math.min(100,v.ratio*100):0)+'%"></i></div></article>'}).join('');
let details=r.rows.map((v,i)=>{let active=v.state==='calc';return '<details class="calc-detail" open><summary><span class="step">0'+(i+1)+'</span>'+v.name+'<span class="badge '+(v.status==='不通過'?'fail':v.state==='review'?'review':active?'':'na')+'">'+v.status+'</span></summary><div class="detail-content"><p><b>規範：</b>'+v.ref+'<br><b>條件：</b>'+esc(v.condition)+'</p>'+(active?'<div class="equation">'+esc(v.formula)+'</div><div class="substitution">'+esc(v.sub)+'</div><div class="answer">'+(asd?'Ω = '+v.omega+'；Rn / Ω = '+num(v.rn,2)+' / '+v.omega:'φ = '+v.phi+'；φRn = '+v.phi+' × '+num(v.rn,2))+' = <b>'+num(v.cap,2)+' kgf</b><br>P / '+(asd?'(Rn/Ω)':'(φRn)')+' = '+num(current.P,2)+' / '+num(v.cap,2)+' = <b>'+num(v.ratio,4)+'</b> '+(v.ratio<=1?'≤':'&gt;')+' 1.0 → '+v.status+'</div>':'<div class="equation">'+(v.state==='review'?'現有公式無法對此條件作出通過判定，須由結構專業人員另行分析。':'依目前載重或拘束條件，此項極限狀態不適用，不列入容量比較。')+'</div>')+(v.note?'<p>'+esc(v.note)+'</p>':'')+'</div></details>';}).join('');
$('output').innerHTML=head+'<div class="result-grid">'+cards+'</div><div class="process-heading"><h2>逐項計算過程</h2><button class="secondary" id="toggle">收合全部</button></div>'+details;$('toggle').onclick=()=>{let ds=[...document.querySelectorAll('.calc-detail')],open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);$('toggle').textContent=open?'收合全部':'展開全部'};try{localStorage.setItem('web-check-v1',JSON.stringify(current));}catch(e){} }
function download(data,name,type){let url=URL.createObjectURL(new Blob([data],{type}));let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportSheets(){if(result.errors.length)return;let x=current,r=result,code=$('code').selectedOptions[0].textContent,date=new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}),names=Object.fromEntries(fields.map(f=>[f[0],f[1]]));let inputRows=[['輸入項目','符號','數值','單位／說明'],['專案','',x.project,''],['構材','',x.member,''],['規範','',code,''],['匯出時間','',date,'Asia/Taipei'],...fields.map(([key,label,unit])=>[label,key,x[key],unit]),['受壓模式','',x.load==='double'?'雙側等值相向壓力，各為 P':'單側集中壓力',''],['相對側移','',x.relative==='free'?'未拘束':'已拘束',''],['受壓翼板轉動','',x.rotation==='yes'?'有拘束':'無拘束',''],['雙側平移拘束','',x.translation==='yes'?'有拘束':'未確認','']];
let rows=[['檢核項目','規範條文','標稱強度 Rn (kgf)','φ','Ω','可用強度 (kgf)','需求 P (kgf)','需求／容量比','判定'],...r.rows.map((v,i)=>{let n=i+2;return [v.name,v.ref,v.state==='calc'?v.rn:'—',x.code==='aisc-asd'?'—':v.phi,x.code==='aisc-asd'?v.omega:'—',v.state==='calc'?{f:x.code==='aisc-asd'?'C'+n+'/E'+n:'C'+n+'*D'+n,v:v.cap}:'—',x.P,v.state==='calc'?{f:'G'+n+'/F'+n,v:v.ratio}:'—',v.status]})];let process=[['檢核項目','規範／分支條件','計算公式','代入過程','容量與比較','備註'],...r.rows.map(v=>[v.name,v.ref+'\n'+v.condition,v.state==='calc'?v.formula:'不適用或需另行評估',v.state==='calc'?v.sub:'未計算容量',v.state==='calc'?(x.code==='aisc-asd'?'Ω = '+v.omega+'；Rn/Ω':'φ = '+v.phi+'；φRn')+' = '+v.cap+' kgf；P = '+x.P+' kgf；D/C = '+v.ratio+'；'+v.status:v.status,v.note])];let notes=[['說明','內容'],['總結',!r.pass?'有項目不通過':r.review?'部分條件需另行評估':'所列適用項目通過'],['計算快照','Excel 為匯出時的計算紀錄；輸入與標稱強度為快照，容量與需求比附公式。修改輸入請回網頁重新計算與匯出。'],['適用範圍','無加勁板、雙對稱熱軋 H/I 型鋼；集中壓力垂直翼板且對稱於腹板。雙側僅限同斷面等值相向壓力。'],['單位','尺寸 mm；內部轉 cm；力量 kgf；應力 kgf/cm²；彎矩 kgf·cm；1 kgf = 9.80665 N。台灣經驗公式以 tf/cm² 計算後換算 kgf。'],['未包含','翼板局部彎曲、整體挫屈、剪力、彎矩、疲勞、載重組合與加勁板設計。正式設計需結構專業人員覆核。'],['台灣規範','96年鋼結構極限設計法第11.2.3～11.2.6節；https://www.nlma.gov.tw/ch/legislation/regsearch/7176'],['台灣原文','https://www.nlma.gov.tw/uploads/files/ea8a881cde01184412b52cefb1a97c2e.pdf'],['AISC','ANSI/AISC 360-22 J10.2～J10.5；https://www.aisc.org/aisc/publications/current-standards/aisc-360'],['輸入提醒','LRFD／台灣極限法輸入因數化需求；ASD 輸入工作載重組合需求。P 為單側傳入力。']];return [{name:'輸入資料',widths:[28,12,48,35],rows:inputRows},{name:'檢核摘要',widths:[23,28,23,10,10,23,22,23,18],rows},{name:'計算過程',widths:[23,45,60,85,65,70],rows:process,heights:[30,95,110,110,110]},{name:'規範與說明',widths:[24,115],rows:notes,heights:[30,35,55,55,65,65,60,50,50,50]}];}
$('excel').onclick=()=>{try{let bytes=SimpleXLSX.workbook(exportSheets());download(bytes,'型鋼腹板檢核_'+(current.member||'計算書').replace(/[\\/:*?"<>|]/g,'_')+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('已匯出 Excel 計算書');}catch(e){toast('匯出失敗：'+e.message)}};
let printState=[];window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true)});window.addEventListener('afterprint',()=>document.querySelectorAll('details').forEach((d,i)=>d.open=printState[i]??true));$('print').onclick=()=>window.print();$('inputs').addEventListener('submit',e=>e.preventDefault());$('inputs').addEventListener('input',render);$('inputs').addEventListener('change',render);$('syncH').onclick=()=>{$('h').value=Number($('d').value)-2*Number($('k').value);render()};$('reset').onclick=()=>{apply(SteelCalc.defaults);toast('已載入預設範例')};$('save').onclick=()=>download(JSON.stringify({version:1,inputs:current},null,2),'型鋼輸入.json','application/json');$('restore').onclick=()=>$('file').click();$('file').onchange=async()=>{try{let obj=JSON.parse(await $('file').files[0].text());if(obj.version!==1||!obj.inputs||allKeys.some(k=>!(k in obj.inputs)))throw Error('檔案格式不符');let x=obj.inputs;for(let k of fields.map(v=>v[0]))if(typeof x[k]!=='number'||!Number.isFinite(x[k]))throw Error('數值格式不符');if(!['tw','aisc-lrfd','aisc-asd'].includes(x.code)||!['yes','no'].includes(x.rotation)||!['yes','no'].includes(x.translation)||!['single','double'].includes(x.load)||!['free','braced'].includes(x.relative))throw Error('條件格式不符');apply(x);toast('已載入輸入資料')}catch(e){toast('無法載入：'+e.message)}finally{$('file').value=''}};
let initial=SteelCalc.defaults;try{let saved=JSON.parse(localStorage.getItem('web-check-v1'));if(saved&&allKeys.every(k=>k in saved))initial=saved}catch(e){}apply(initial);
